import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.DnrXFDHb.js";const f=JSON.parse('{"title":"Transformer 直觉","description":"","frontmatter":{},"headers":[],"relativePath":"llm/transformer.md","filePath":"llm/transformer.md","lastUpdated":1786350421000}'),n={name:"llm/transformer.md"};function i(o,a,s,p,h,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="transformer-直觉" tabindex="-1">Transformer 直觉 <a class="header-anchor" href="#transformer-直觉" aria-label="Permalink to &quot;Transformer 直觉&quot;">​</a></h1><p>一句话：Transformer 是现代大语言模型的核心架构，它让模型在处理 token 时能动态关注上下文里的相关部分。</p><h2 id="为什么需要-transformer" tabindex="-1">为什么需要 Transformer <a class="header-anchor" href="#为什么需要-transformer" aria-label="Permalink to &quot;为什么需要 Transformer&quot;">​</a></h2><p>语言不是一个词一个词孤立理解的。一个词的含义取决于上下文：</p><ul><li>“苹果”可能是水果，也可能是公司。</li><li>“它”指代谁，需要看前文。</li><li>代码里的变量含义，要看定义和调用位置。</li></ul><p>Transformer 的优势是可以并行处理序列，并通过注意力机制建立 token 之间的关系。</p><h2 id="attention-是什么" tabindex="-1">Attention 是什么 <a class="header-anchor" href="#attention-是什么" aria-label="Permalink to &quot;Attention 是什么&quot;">​</a></h2><p>Attention 可以理解为“当前 token 应该关注哪些上下文 token”。</p><p>例如模型看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>小明把书放进书包，因为它很重。</span></span></code></pre></div><p>模型需要判断“它”更可能指书还是书包。Attention 会帮助模型在上下文中给相关 token 更高权重。</p><h2 id="self-attention" tabindex="-1">Self-Attention <a class="header-anchor" href="#self-attention" aria-label="Permalink to &quot;Self-Attention&quot;">​</a></h2><p>Self-Attention 是同一段输入内部互相关注。每个 token 都会根据上下文生成新的表示。</p><p>直观流程：</p><ol><li>把 token 转成向量。</li><li>计算 token 之间的相关性。</li><li>用相关性加权汇总上下文信息。</li><li>得到更懂上下文的新向量。</li></ol><p>这不是人工写死的规则，而是在训练中学出来的模式。</p><h2 id="多层和多头" tabindex="-1">多层和多头 <a class="header-anchor" href="#多层和多头" aria-label="Permalink to &quot;多层和多头&quot;">​</a></h2><p>多头注意力可以理解为从不同角度看上下文：</p><ul><li>一个头可能关注语法关系。</li><li>一个头可能关注指代关系。</li><li>一个头可能关注代码结构。</li><li>一个头可能关注格式边界。</li></ul><p>多层 Transformer 会逐步形成更抽象的表示。底层可能更关注局部模式，高层可能更关注任务和语义。</p><h2 id="位置编码" tabindex="-1">位置编码 <a class="header-anchor" href="#位置编码" aria-label="Permalink to &quot;位置编码&quot;">​</a></h2><p>Attention 本身不天然知道顺序，所以模型需要位置信息。位置编码或相关机制会告诉模型 token 在序列中的位置。</p><p>这对语言很重要，因为：</p><ul><li>“猫追狗”和“狗追猫”词相同但意思不同。</li><li>代码、表格和列表都依赖顺序。</li><li>长上下文需要识别远近关系。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>“Attention 就是人类注意力”：只是一个数学机制，不等同于意识。</li><li>“Transformer 会真正理解”：它学到的是可泛化的表示和模式，不能自动保证事实正确。</li><li>“上下文越长越强”：长上下文还需要检索、排序和压缩，不能无限堆材料。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读 <a href="/llm/training-alignment">训练、微调与对齐</a>，理解 Transformer 的通用能力如何形成并适应具体任务。</p>',28)])])}const c=e(n,[["render",i]]);export{f as __pageData,c as default};
